function browserStorage(){try{return globalThis.localStorage;}catch{return undefined;}}
export function initializeLanguage(storage=browserStorage(),browserLanguage=globalThis.navigator?.language){
  let saved;try{saved=storage?.getItem(LANGUAGE_KEY);}catch{/* Storage may be disabled. */}
  language=saved==='zh'||saved==='en'?saved:/^zh(?:-|$)/i.test(browserLanguage??'zh')?'zh':'en';
  return language;
}
export const getLanguage=()=>language;
export function setLanguage(next,storage=browserStorage()){
  if(next!=='zh'&&next!=='en')return language;
  language=next;try{storage?.setItem(LANGUAGE_KEY,next);}catch{/* Switching still works in memory. */}
  return language;
}
export function t(key,values={}){
  const copy=language==='en'&&Object.hasOwn(english,key)?english[key]:String(key);
  return copy.replace(/\{(\w+)\}/g,(match,name)=>Object.hasOwn(values,name)?String(values[name]):match);
}
export function applyTranslations(root=document){
  root.querySelectorAll('[data-i18n]').forEach(el=>{el.textContent=t(el.dataset.i18n);});
  for(const attr of ['title','aria-label','placeholder','content']){
    root.querySelectorAll(`[data-i18n-${attr}]`).forEach(el=>el.setAttribute(attr,t(el.getAttribute(`data-i18n-${attr}`))));
  }
}
